 9	method Partition( m: multiset<int> )
10	        returns( pre: multiset<int>, p: int, post: multiset<int> )
11	    requires |m| > 0;
12	    ensures p in m;
13	    ensures m == pre+multiset{p}+post;
14	    ensures forall z | z in pre :: z <= p;
15	    ensures forall z | z in post :: z >= p;
16	{
17	    p :| p in m;
18	    var m' := m;
19	    m' := m' - multiset{p};
20	    pre := multiset{};
21	    post := multiset{};
22	    while m' != multiset{}
23	        decreases m';
24	        invariant m == m' + pre + multiset{p} + post;
25	        invariant forall k | k in pre :: k <= p;
26	        invariant forall k | k in post :: k >= p;
27	
28	    {
29	        var temp :| temp in m';
30	        m' := m' - multiset{temp};
31	        if temp <= p
32	        {
33	            pre := pre + multiset{temp};
34	        }
35	        else
36	        {
37	            post := post + multiset{temp};
38	        }
39	    }
40	    return pre,p,post;
41	        
42	}
