50	method QuickSelect( m: multiset<int>, k: int )
51	        returns( pre: multiset<int>, kth: int, post: multiset<int> )
52	    decreases m;
53	    ensures kth in m;
54	    ensures m == pre+multiset{kth}+post;
55	    ensures |pre| == k;
56	    ensures forall z | z in pre :: z <= kth;
57	    ensures forall z | z in post :: z >= kth;
58	{
59	    pre,kth,post := Partition(m);
60	    assert m == pre + multiset{kth} + post;
61	    if |pre| != k
62	    {
63	        if k > |pre|
64	        {
65	        
66	            var pre',p,post' := QuickSelect(post,k-|pre| - 1);
67	            assert pre' + multiset{p} + post' == post;
68	            pre := pre + multiset{kth} + pre';
69	            post := post - pre' - multiset{p};
70	            kth := p;
71	
72	        }
73	        else if k < |pre|
74	        {
75	            var pre',p,post' := QuickSelect(pre,k);
76	            pre := pre - multiset{p} - post';
77	            post := post + multiset{kth} + post';
78	            kth := p;
79	
80	        }
81	    }
82	    else{
83	        return pre,kth,post;
84	    } 
85	}

